function zp_suite_238_strony_no_double_flash_js(){ ?>
<script id="zp-suite-238-strony-no-double-flash">
(function(){
  try{
    var root=document.getElementById('zpWebHeroKat');
    if(!root) return;
    root.setAttribute('data-ready','1');
    var nativeSet=root.setAttribute;
    root.setAttribute=function(name,value){
      if(String(name).toLowerCase()==='data-ready' && String(value)==='0') value='1';
      return nativeSet.call(this,name,value);
    };
  }catch(e){}
})();
</script>
<?php }
add_action('wp_footer', 'zp_suite_238_strony_no_double_flash_js', PHP_INT_MAX);

/* ZP Suite v2.2.410 — migration for saved CMS/options that may still hold the old Strony H1. */
add_action('plugins_loaded', function(){
  $target = 'Strony internetowe Katowice — strony firmowe gotowe na SEO i zapytania';
  $rows = get_option('zp_suite_katowice_page', []);
  if (is_array($rows) && isset($rows[0]) && is_array($rows[0])) {
    $current = trim(wp_strip_all_tags((string)($rows[0]['hero_h1'] ?? '')));
    if ($current === '' || stripos($current, 'projektowanie stron WWW') !== false || stripos($current, 'projektowanie stron www') !== false) {
      $rows[0]['hero_h1'] = $target;
      update_option('zp_suite_katowice_page', $rows, false);
    }
  }
  $sections = get_option('zp_suite_katowice_sections', []);
  if (is_array($sections) && isset($sections['hero']) && is_string($sections['hero'])) {
    $hero = $sections['hero'];
    $hero2 = preg_replace('/<h1([^>]*)id=["\']zpWebHeroKatTitle["\']([^>]*)>.*?<\/h1>/is', '<h1 id="zpWebHeroKatTitle" class="zpServiceHeroH1"><span class="zpH1Emphasis">Strony internetowe Katowice</span> — strony, które pracują</h1>', $hero, 1);
    if (is_string($hero2) && $hero2 !== $hero) {
      $sections['hero'] = $hero2;
      update_option('zp_suite_katowice_sections', $sections, false);
    }
  }
}, 999);

